const supplierPaidNet = `-- name: SupplierPaidNet :one
SELECT (COALESCE((SELECT sum(sp.amount_paisa) FROM supplier_payments sp WHERE sp.supplier_id = $1 AND sp.voided_at IS NULL), 0)
      - COALESCE((SELECT sum(r.refund_paisa) FROM purchase_returns r JOIN purchases p ON p.id = r.purchase_id
                  WHERE p.supplier_id = $1), 0))::bigint
`

// Live payments less refunds handed back: the pool that settles debts oldest first.
